1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	};
9	
10	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
11	
12	export type ScenarioResult = { premium: number };
13	
14	export type ScenarioOutcome = { results: ScenarioResult[] };
15	
16	type Item = { type: string };
17	
18	type Scenario = { steps: { items: Item[] }[] };
19	
20	const basePremiumOf = (item: Item): number =>
21	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
22	
23	// Adds the surcharge as a separate term rather than scaling by 1.1, because
24	// `100 * 1.1` is 115.00000000000001 in binary floating point.
25	const withFirstInsuranceSurcharge = (amount: number): number =>
26	  amount + amount * FIRST_INSURANCE_SURCHARGE_RATE;
27	
28	const quotePremium = (items: Item[]): number => {
29	  const basePremium = items.reduce<number>(
30	    (total, item) => total + basePremiumOf(item),
31	    0,
32	  );
33	
34	  return withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
35	};
36	
37	export const runScenario = (scenario: unknown): ScenarioOutcome => {
38	  const { steps } = scenario as Scenario;
39	
40	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
41	
42	  return { results };
43	};
